export default {"file":"offline.html","title":"Connection lost · Schoolix","htmlClass":"","bodyClass":"","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n  <main class=\"offline-panel\">\r\n    <div class=\"mark\"><img src=\"/schoolix-app-icon.svg\" alt=\"\"></div>\r\n    <div class=\"connection-state\" id=\"connectionState\"><span class=\"connection-dot\"></span><span id=\"connectionLabel\">No internet connection</span></div>\r\n    <h1 id=\"offlineTitle\">You’re currently offline</h1>\r\n    <p id=\"offlineMessage\">Schoolix can open saved pages, but live records, attendance, and updates need an internet connection. Reconnect and try again.</p>\r\n    <button type=\"button\" id=\"retryButton\">Try again</button>\r\n    <p class=\"helper\" id=\"helperText\">We’ll automatically let you know when you’re back online.</p>\r\n  </main>\r\n  <script>\r\n    (function () {\r\n      var state = document.getElementById(\"connectionState\");\r\n      var label = document.getElementById(\"connectionLabel\");\r\n      var title = document.getElementById(\"offlineTitle\");\r\n      var message = document.getElementById(\"offlineMessage\");\r\n      var button = document.getElementById(\"retryButton\");\r\n      var helper = document.getElementById(\"helperText\");\r\n      function refreshState() {\r\n        var online = navigator.onLine;\r\n        state.classList.toggle(\"is-online\", online);\r\n        label.textContent = online ? \"Connection restored\" : \"No internet connection\";\r\n        title.textContent = online ? \"You’re back online\" : \"You’re currently offline\";\r\n        message.textContent = online ? \"Your connection is back. Reload this page to continue with Schoolix.\" : \"Schoolix can open saved pages, but live records, attendance, and updates need an internet connection. Reconnect and try again.\";\r\n        button.textContent = online ? \"Continue\" : \"Try again\";\r\n        helper.textContent = online ? \"Ready when you are.\" : \"We’ll automatically let you know when you’re back online.\";\r\n      }\r\n      button.addEventListener(\"click\", function () { window.location.reload(); });\r\n      window.addEventListener(\"online\", refreshState);\r\n      window.addEventListener(\"offline\", refreshState);\r\n      refreshState();\r\n    }());\r\n  </script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{},"text":"\r\n    (function () {\r\n      var state = document.getElementById(\"connectionState\");\r\n      var label = document.getElementById(\"connectionLabel\");\r\n      var title = document.getElementById(\"offlineTitle\");\r\n      var message = document.getElementById(\"offlineMessage\");\r\n      var button = document.getElementById(\"retryButton\");\r\n      var helper = document.getElementById(\"helperText\");\r\n      function refreshState() {\r\n        var online = navigator.onLine;\r\n        state.classList.toggle(\"is-online\", online);\r\n        label.textContent = online ? \"Connection restored\" : \"No internet connection\";\r\n        title.textContent = online ? \"You’re back online\" : \"You’re currently offline\";\r\n        message.textContent = online ? \"Your connection is back. Reload this page to continue with Schoolix.\" : \"Schoolix can open saved pages, but live records, attendance, and updates need an internet connection. Reconnect and try again.\";\r\n        button.textContent = online ? \"Continue\" : \"Try again\";\r\n        helper.textContent = online ? \"Ready when you are.\" : \"We’ll automatically let you know when you’re back online.\";\r\n      }\r\n      button.addEventListener(\"click\", function () { window.location.reload(); });\r\n      window.addEventListener(\"online\", refreshState);\r\n      window.addEventListener(\"offline\", refreshState);\r\n      refreshState();\r\n    }());\r\n  "},{"attributes":{"src":"schoolix-polish.js"},"text":""}]};
